-- CreateEnum
CREATE TYPE "session_revoke_reason" AS ENUM ('LOGOUT', 'PASSWORD_CHANGED', 'USER_DISABLED', 'MANAGER_REVOKED', 'SUPERSEDED');

-- CreateEnum
CREATE TYPE "audit_actor_type" AS ENUM ('USER', 'SYSTEM', 'ANONYMOUS');

