-- ===========================================================================
-- HAND-WRITTEN — everything below this line is reviewed by a human, not
-- generated. Prisma cannot express CHECK constraints, partial indexes,
-- functions or triggers.
--
-- NOTE ON FOREIGN KEYS: exactly three exist, all created above, and NONE of
-- them is on "audit_log"."session_id". That absence is deliberate and
-- load-bearing. Sessions are operational state that a retention policy must be
-- able to purge; audit rows are permanent. A foreign key between them would
-- make session retention impossible, because essentially every session
-- accumulates at least one audit row. The column keeps the id as a historical
-- reference instead, exactly as "entity_id" does. An integration test asserts
-- this absence, so the constraint cannot be reintroduced by accident.
-- ===========================================================================

-- --- app_user CHECK constraints --------------------------------------------

-- Lower case is what makes the identifier case-insensitively unique without
-- requiring the citext extension, which would need elevated privileges.
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_username_lowercase_chk"
    CHECK ("username" = lower("username"));

ALTER TABLE "app_user" ADD CONSTRAINT "app_user_username_format_chk"
    CHECK ("username" ~ '^[a-z0-9._-]{3,32}$');

ALTER TABLE "app_user" ADD CONSTRAINT "app_user_display_name_chk"
    CHECK (btrim("display_name") <> '' AND length("display_name") <= 120);

-- Makes a plaintext password, a bcrypt hash, or an Argon2 variant other than
-- argon2id structurally impossible to store, whatever the application does.
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_password_hash_argon2id_chk"
    CHECK ("password_hash" LIKE '$argon2id$%');

ALTER TABLE "app_user" ADD CONSTRAINT "app_user_failed_login_count_chk"
    CHECK ("failed_login_count" >= 0);

-- A disabled account always records when it was disabled, and an active one
-- never claims to have been.
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_disabled_consistency_chk"
    CHECK (("status" = 'DISABLED') = ("disabled_at" IS NOT NULL));

-- --- user_session CHECK constraints -----------------------------------------

-- SHA-256 output is exactly 32 bytes. A shorter value would mean something
-- other than a hash reached this column.
ALTER TABLE "user_session" ADD CONSTRAINT "user_session_token_hash_length_chk"
    CHECK (octet_length("token_hash") = 32);

ALTER TABLE "user_session" ADD CONSTRAINT "user_session_revocation_consistency_chk"
    CHECK (("revoked_at" IS NULL) = ("revoked_reason" IS NULL));

ALTER TABLE "user_session" ADD CONSTRAINT "user_session_absolute_after_created_chk"
    CHECK ("absolute_expires_at" > "created_at");

ALTER TABLE "user_session" ADD CONSTRAINT "user_session_idle_after_created_chk"
    CHECK ("idle_expires_at" > "created_at");

-- The 12-hour absolute cap becomes a database invariant: a bug in the rolling
-- idle-renewal path cannot extend a session past it, because the row would fail
-- to write at all.
ALTER TABLE "user_session" ADD CONSTRAINT "user_session_idle_within_absolute_chk"
    CHECK ("idle_expires_at" <= "absolute_expires_at");

-- --- audit_log CHECK constraints --------------------------------------------

-- Dotted lower-case action names, e.g. auth.login.failed. `action` is TEXT
-- rather than an enum because every future milestone adds actions, and an enum
-- would cost an ALTER TYPE migration each time.
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_format_chk"
    CHECK ("action" ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$');

ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_entity_type_format_chk"
    CHECK ("entity_type" ~ '^[a-z][a-z0-9_]*$');

-- "who did this" is never ambiguous: a USER row always names the user, and a
-- SYSTEM or ANONYMOUS row never does.
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_actor_consistency_chk"
    CHECK (("actor_type" = 'USER') = ("actor_user_id" IS NOT NULL));

ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_user_agent_length_chk"
    CHECK (length("user_agent") <= 256);

-- Last line of defence against a password hash reaching the audit trail. The
-- application already refuses to build such a payload; this makes the database
-- refuse to store one even if that code is bypassed or changed.
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_no_secret_material_chk"
    CHECK (
        coalesce("before"::text, '')   NOT LIKE '%$argon2%' AND
        coalesce("after"::text, '')    NOT LIKE '%$argon2%' AND
        coalesce("metadata"::text, '') NOT LIKE '%$argon2%'
    );

-- --- Partial index ----------------------------------------------------------

-- The key a future session-purge job will use. Partial, because only
-- unrevoked sessions are candidates for expiry-based cleanup.
CREATE INDEX "user_session_absolute_expires_at_active_idx"
    ON "user_session" ("absolute_expires_at")
    WHERE "revoked_at" IS NULL;

-- --- Append-only and no-delete enforcement ----------------------------------

-- One function serves both tables. SQLSTATE 23001 (restrict_violation) gives
-- tests a stable code to assert on instead of matching a message string.
CREATE OR REPLACE FUNCTION "raise_append_only_violation"() RETURNS trigger
    LANGUAGE plpgsql AS $fn$
BEGIN
    RAISE EXCEPTION '% is protected; % is not permitted', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$fn$;

-- audit_log is append-only. The TRUNCATE trigger is not optional: TRUNCATE
-- bypasses row-level triggers entirely, so without it the whole guarantee would
-- be one statement away from gone.
CREATE TRIGGER "audit_log_no_update"
    BEFORE UPDATE ON "audit_log"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "audit_log_no_delete"
    BEFORE DELETE ON "audit_log"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "audit_log_no_truncate"
    BEFORE TRUNCATE ON "audit_log"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

-- app_user rows are permanent historical records: creation is audited, and
-- later financial rows will name the actor. Deactivation is status = DISABLED.
CREATE TRIGGER "app_user_no_delete"
    BEFORE DELETE ON "app_user"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "app_user_no_truncate"
    BEFORE TRUNCATE ON "app_user"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

-- user_session deliberately carries no such trigger. It is the one table here
-- that is meant to be prunable.

-- NOTE ON COMPLETENESS: a table owner can still run
-- `ALTER TABLE ... DISABLE TRIGGER`. Closing that gap needs a runtime database
-- role that does not own these tables and holds only INSERT and SELECT on
-- audit_log. That is a production hardening item, not a Milestone 1 change,
-- because it would alter the compose file, both environment files and CI for a
-- benefit that only exists in a production that does not yet exist.
